WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_mm_people'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多人同线相遇', 'kp-trv-mm-people', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多人同线相遇"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "甲、乙、丙三人同在一条直线上，两人一端，一人另一端，引发连续两次相遇。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲乙在A地，丙在B地。三人同时出发，甲丙先相遇，5 分钟后乙丙相遇”。这是非常经典的模型。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题目必然存在两套【相遇公式】。总距离 S 是一样的！"}]}, {"type": "katexBlock", "attrs": {"content": "S = (V_甲 + V_丙) \\times t_1 \\quad ; \\quad S = (V_乙 + V_丙) \\times (t_1 + 5)"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画出三人同线相遇图] --> B[写出第一次(甲丙)相遇的等式]\nB --> C[写出第二次(乙丙)相遇的等式]\nC --> D[因为起点端点一样, 两个等式的 S 相等]\nD --> E[用等号连接左右两边, 解出未知数(通常是时间 t1 或 某人的速度)]"}}]}$$ AS jsonb), NULL, '多人同线相遇的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "多人同线相遇"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_mm_people", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
